import openpyxl

wb = openpyxl.load_workbook('gdp.xlsx')
ws = wb['Task']

# Find all formula cells and verify they're only where expected
expected_formula_cells = set()

# I9-L9 (pre-existing year formulas)
for col in range(9, 13):
    expected_formula_cells.add((9, col))

# Step 1: H12:L17, H19:L24, H26:L31
for row in list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32)):
    for col in range(8, 13):
        expected_formula_cells.add((row, col))

# Step 2: H35:L40
for row in range(35, 41):
    for col in range(8, 13):
        expected_formula_cells.add((row, col))

# Step 2 stats: H42:L47
for row in range(42, 48):
    for col in range(8, 13):
        expected_formula_cells.add((row, col))

# Step 3: H50:L50
for col in range(8, 13):
    expected_formula_cells.add((50, col))

# Check all cells for formulas
unexpected = []
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=20):
    for cell in row:
        if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
            key = (cell.row, cell.column)
            if key not in expected_formula_cells:
                unexpected.append(f"{cell.coordinate}: {cell.value}")

if unexpected:
    print("Unexpected formula cells:")
    for u in unexpected:
        print(f"  {u}")
else:
    print("All formula cells are where expected!")

print(f"\nExpected formula cells count: {len(expected_formula_cells)}")

